//! NeatWork desktop interface (Slint). It rebuilds the windows of the Java
//! program NeatWork 2024 on top of `neatwork-core`, and adds a drawing of
//! the network.

mod actions;
mod app;
mod drawing;
mod files;
mod i18n;
mod nw5;
mod nw5_actions;
mod nw5_tables;
mod support;
mod table;

use std::cell::RefCell;
use std::rc::Rc;

use slint::{ComponentHandle, ModelRc, SharedString, VecModel};

use app::{App, Pending};

/// Code generated by Slint from `ui/*.slint`.
mod ui {
    // Generated code: the workspace lints do not apply to it.
    #![allow(
        clippy::all,
        clippy::pedantic,
        clippy::unwrap_used,
        clippy::expect_used
    )]
    slint::include_modules!();
}
pub use ui::*;

thread_local! {
    static APP: RefCell<Option<Rc<RefCell<App>>>> = const { RefCell::new(None) };
}

/// Run `f` on the application state (main thread only). Callbacks of the
/// window and results of the worker threads go through this function.
pub fn with_app(f: impl FnOnce(&mut App)) {
    let app = APP.with(|a| a.borrow().clone());
    if let Some(app) = app
        && let Ok(mut a) = app.try_borrow_mut()
    {
        f(&mut a);
    }
}

pub fn app_strings(v: Vec<String>) -> ModelRc<SharedString> {
    let v: Vec<SharedString> = v.into_iter().map(SharedString::from).collect();
    ModelRc::new(VecModel::from(v))
}

/// Run the steps of `NEATWORK_GUI_STEPS` after `delay` ms; `wait=MS`
/// delays the steps after it.
fn run_steps(steps: Vec<String>, delay: u64) {
    slint::Timer::single_shot(std::time::Duration::from_millis(delay), move || {
        for (i, step) in steps.iter().enumerate() {
            let (k, v) = step.split_once('=').unwrap_or((step.as_str(), ""));
            if k == "wait" {
                run_steps(steps[i + 1..].to_vec(), v.parse().unwrap_or(500));
                return;
            }
            with_app(|app| app.run_step(k, v));
        }
    });
}

pub fn idx(i: i32) -> usize {
    usize::try_from(i).unwrap_or(usize::MAX)
}

fn main() -> Result<(), slint::PlatformError> {
    let ui = MainWindow::new()?;
    // The folder chosen with File > Working Folder, else the current folder
    // (as the Java program).
    let base = files::read_work_folder()
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| ".".into()));
    let app = Rc::new(RefCell::new(App::new(&ui, base)));
    APP.with(|a| *a.borrow_mut() = Some(app.clone()));

    // texts of the Java bundles
    {
        let msgs = i18n::Messages::new();
        ui.global::<T>()
            .on_lookup(move |lang, key| SharedString::from(msgs.get(lang, &key)));
    }

    let s = ui.global::<AppState>();
    s.on_menu(|a| with_app(|app| app.menu(&a)));
    s.on_select_project(|i| {
        with_app(|app| {
            if idx(i) < app.projects.len() {
                app.current = Some(idx(i));
                if let Some(ui) = app.ui() {
                    ui.global::<AppState>().set_pane_tab(0);
                }
                app.refresh();
            } else if idx(i) - app.projects.len() < app.nw5.tabs.len() {
                // a NW5 project tab
                app.nw5.current = Some(idx(i) - app.projects.len());
                app.current = None;
                app.refresh();
            }
        });
    });
    nw5_actions::connect(&ui);
    s.on_text_apply(|t| with_app(|app| app.text_apply(&t)));
    s.on_text_undo(|| with_app(|app| app.refresh_text()));
    s.on_table_edited(|id, r, c, t| with_app(|app| app.table_edited(id, idx(r), idx(c), &t)));
    s.on_table_row_clicked(|id, r, ctrl, shift| {
        with_app(|app| app.table_row_clicked(id, idx(r), ctrl, shift))
    });
    s.on_table_action(|id, a| with_app(|app| app.table_action(id, &a)));

    // tree view
    s.on_tree_clicked(|row, col| {
        with_app(|app| {
            let Some(i) = app.current else {
                return;
            };
            let p = &app.projects[i];
            let name = support::tree_layout(p.name(), p.network()).and_then(|l| {
                l.cell(idx(row), idx(col))
                    .map(|c| c.kind.text().to_string())
            });
            app.projects[i].selected_node = name;
            app.refresh_tree();
            app.refresh_network();
        });
    });
    s.on_tree_search(|text| {
        with_app(|app| {
            let Some(p) = app.cur() else {
                return;
            };
            let found = support::tree_layout(p.name(), p.network())
                .and_then(|l| neatwork_core::gui_support::search(&l, &text));
            if let (Some((r, c)), Some(ui)) = (found, app.ui()) {
                let s = ui.global::<AppState>();
                s.set_tree_focus_row(r as i32);
                s.set_tree_focus_col(c as i32);
                s.set_tree_focus_serial(s.get_tree_focus_serial() + 1);
            }
        });
    });

    // drawing
    s.on_net_node_clicked(|i| {
        with_app(|app| {
            let Some(c) = app.current else {
                return;
            };
            let name = app.projects[c]
                .network()
                .nodes
                .get(idx(i))
                .map(|n| n.name.clone());
            app.projects[c].selected_node = name;
            app.refresh_network();
            app.refresh_tree();
        });
    });
    s.on_net_view_changed(|| with_app(|app| app.refresh_network()));

    // simulation pane
    s.on_sim_select(|i| {
        with_app(|app| {
            app.select_simulation(idx(i));
            app.refresh_simulations();
            app.refresh_network();
        });
    });
    s.on_sim_table_select(|k| {
        with_app(|app| {
            if let Some(ui) = app.ui() {
                ui.global::<AppState>().set_sim_table_kind(k);
            }
            app.refresh_simulations();
        });
    });

    // dialogs
    s.on_msg_answer(|yes| with_app(|app| app.msg_answer(yes)));
    s.on_fd_browse(|| with_app(|app| app.fd_browse()));
    s.on_fd_pick(|i, double| with_app(|app| app.fd_pick(idx(i), double)));
    s.on_fd_action(|| with_app(|app| app.fd_action()));
    s.on_fd_cancel(|| with_app(|app| app.fd_cancel()));
    s.on_md_param_edited(|i, t| with_app(|app| app.md_param_edited(idx(i), &t)));
    s.on_md_add_constraint(|| with_app(|app| app.md_add_constraint()));
    s.on_md_delete_constraint(|| with_app(|app| app.md_delete_constraint()));
    s.on_md_run(|| with_app(|app| app.md_run()));
    s.on_md_abort(|| with_app(|app| app.md_abort()));
    s.on_pg_close(|| with_app(|app| app.pg_close()));
    s.on_td_close(|| with_app(|app| app.td_close()));
    s.on_info_close(|| {
        with_app(|app| {
            if let Some(ui) = app.ui() {
                ui.global::<AppState>().set_info_visible(false);
            }
        });
    });
    s.on_qc_apply(|| with_app(|app| app.qc_apply()));
    s.on_qc_close(|| {
        with_app(|app| {
            if let Some(ui) = app.ui() {
                ui.global::<AppState>().set_qc_visible(false);
            }
        });
    });
    s.on_db_close(|| {
        with_app(|app| {
            if let Some(ui) = app.ui() {
                ui.global::<AppState>().set_db_visible(false);
            }
        });
    });
    s.on_ns_run(|| with_app(|app| app.ns_run()));
    s.on_ns_close(|| with_app(|app| app.ns_close()));
    s.on_ts_ok(|| with_app(|app| app.ts_ok()));

    // closing the window asks for a confirmation, as "Exit" does
    ui.window().on_close_requested(|| {
        with_app(|app| {
            let text = app.tr("FrameNeatwork.Do_you_really_want_to_quit");
            let title = app.tr("FrameNeatwork.Confirmation_Dialog");
            app.message(&title, &text, 1, Pending::Exit);
        });
        slint::CloseRequestResponse::KeepWindowShown
    });

    with_app(|app| app.refresh());
    // open the files given on the command line
    for arg in std::env::args().skip(1) {
        with_app(|app| app.open_path(std::path::Path::new(&arg)));
    }
    // NEATWORK_GUI_STEPS: interface actions run at start, for checks and
    // screenshots without input injection. Steps are separated by ';':
    // tab=N, menu=ACTION, layout=N, color=N, simtable=N, select=NODE.
    if let Ok(steps) = std::env::var("NEATWORK_GUI_STEPS") {
        let steps: Vec<String> = steps
            .split(';')
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .collect();
        run_steps(steps, 300);
    }
    ui.run()
}
